// IconButton, AS GRAPH SOURCE (#3678, epic #3604) — a pure shared/ui control authored as DATA. Its
// `provides: "@/shared/ui/controls/IconButton"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). Transcribed verbatim; deps stay registered code.
// IconButton (#1753) — the one button for icon-glyph actions (close / remove / cancel), replacing the
// five wrappers (`.x`, the misspelled-and-unstyled `.iconbtn`, `.btn ghost` at three sizes, `.mini`,
// fully-inline) and two glyphs (`×` U+00D7 vs `✕` U+2715) the app had hand-rolled. Renders the
// canonical close glyph by default; `aria-label` is REQUIRED so every icon button is accessible.
import type { ReactNode, CSSProperties, MouseEvent } from "react";

/** The one canonical close/dismiss glyph. */
export const CLOSE_GLYPH = "✕";

export interface IconButtonProps {
  /** Required — icon buttons have no text, so they must carry an accessible name. */
  "aria-label": string;
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void;
  /** The glyph/icon; defaults to the canonical close glyph. */
  children?: ReactNode;
  /** Hit-area size: md = 24px (default, modal/panel/banner headers) · sm = 20px · xs = 16px (inline chip removers). */
  size?: "md" | "sm" | "xs";
  /** Red hover (destructive). */
  danger?: boolean;
  disabled?: boolean;
  title?: string;
  className?: string;
  style?: CSSProperties;
}

export function IconButton({
  "aria-label": ariaLabel, onClick, children, size = "md", danger, disabled, title, className, style,
}: IconButtonProps) {
  const cls = ["icon-btn", size !== "md" && size, danger && "danger", className].filter(Boolean).join(" ");
  return (
    <button type="button" className={cls} aria-label={ariaLabel} title={title ?? ariaLabel} onClick={onClick} disabled={disabled} style={style}>
      {children ?? CLOSE_GLYPH}
    </button>
  );
}

tests.src:
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { IconButton, CLOSE_GLYPH } from "./IconButton";

describe("IconButton", () => {
  it("renders the canonical close glyph by default and exposes its aria-label", () => {
    render(<IconButton aria-label="close" />);
    const btn = screen.getByRole("button", { name: "close" });
    expect(btn).toHaveTextContent(CLOSE_GLYPH);
    expect(btn.className).toContain("icon-btn");
  });

  it("fires onClick", () => {
    const onClick = vi.fn();
    render(<IconButton aria-label="close" onClick={onClick} />);
    fireEvent.click(screen.getByRole("button", { name: "close" }));
    expect(onClick).toHaveBeenCalledTimes(1);
  });

  it("does not fire when disabled", () => {
    const onClick = vi.fn();
    render(<IconButton aria-label="close" disabled onClick={onClick} />);
    const btn = screen.getByRole("button", { name: "close" });
    expect(btn).toBeDisabled();
    fireEvent.click(btn);
    expect(onClick).not.toHaveBeenCalled();
  });

  it("applies size + danger modifier classes", () => {
    const { rerender } = render(<IconButton aria-label="remove" size="xs" danger />);
    let cls = screen.getByRole("button", { name: "remove" }).className;
    expect(cls).toContain("xs");
    expect(cls).toContain("danger");
    rerender(<IconButton aria-label="remove" size="md" />);
    cls = screen.getByRole("button", { name: "remove" }).className;
    expect(cls).not.toContain("xs");
    expect(cls).not.toContain("danger");
  });

  it("renders custom children over the default glyph", () => {
    render(<IconButton aria-label="cancel">cancel</IconButton>);
    expect(screen.getByRole("button", { name: "cancel" })).toHaveTextContent("cancel");
  });
});
